    println!("        matches=\"${{query}}\"");
    println!("    else");
    println!("        matches=\"*\"");
    println!("    fi");
    println!("    local best=\"\"");
    println!("    local best_score=0");
    println!("    while IFS= read -r line; do");
    println!("        path=\"${{line%%:*}}\"");
    println!("        score=\"${{line##*:}}\"");
    println!("        if [[ \"${{path}}\" == *\"${{matches}}\"* ]]; then");
    println!("            if (( score > best_score )); then");
    println!("                best_score=$score");
    println!("                best=$path");
    println!("            fi");
    println!("        fi");
    println!("    done < <(cat \"${{db}}\" 2>/dev/null)");
    println!("    if [[ -n \"${{best}}\" ]]; then");
    println!("        cd \"${{best}}\"");
    println!("    fi");
    println!("}");
    println!();
    println!("export PROMPT_COMMAND=\"_zoxide\"");
