fn print_powershell_init() {
    let dir = get_data_dir().to_string_lossy().to_string();
    let db = get_db_file().to_string_lossy().to_string();
    let version = VERSION;

    println!("function _zoxide() {");
    println!("    $dir = \"{}\"", dir);
    println!("    $db = \"{}\"", db);
    println!("    $query = $args[0]");
    println!("    $matches = if $query -ne \"\" { $query } else { \"*\" }");
    println!("    $best = \"\"");
    println!("    $best_score = 0");
    println!("    foreach ($line in (Get-Content \"$db\" -ErrorAction SilentlyContinue)) {");
    println!("        $parts = $line.Split(\":\")");
    println!("        $path = $parts[0]");
    println!("        $score = [int]$parts[1]");
    println!("        if ($path -like \"*${{matches}}*\") {");
    println!("            if ($score -gt $best_score) {");
    println!("                $best_score = $score");
    println!("                $best = $path");
    println!("            }");
    println!("        }");
    println!("    }");
    println!("    if ($best -ne $null -and $best -ne \"\") {");
    println!("        Set-Location $best");
    println!("    }");
    println!("}");
    println!();
    println!("$env:_ZO_DATA_DIR = \"{}\"", dir);
    println!("$env:_ZO_ECHO = 1");
    println!("$env:_ZO_EXCLUDE_DIRS = \"\"");
    println!("$env:_ZO_MAXAGE = 0");
    println!("$env:_ZO_RESOLVE_SYMLINKS = 0");
    println!("$env:_ZO_FZF_OPTS = \"\"");
