+        print_help();
+        process::exit(1);
+    };
+    
+    match command.as_str() {
+        "add" => add(&args[2..]),
+        "query" => query(&args[2..]),
+        "remove" => remove(&args[2..]),
+        "init" => init(&args[2..]),
+        "import" => import(&args[2..]),
+        "edit" => edit(),
+        _ => {
+            print_help();
+            process::exit(1);
+        }
+    }
